import 'package:flutter/material.dart';import '../models/recordatorio.dart';import '../services/api_service.dart';import 'recordatorio_form.dart';import 'server_settings_screen.dart';
class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{final api=ApiService();late Future<List<Recordatorio>> future=api.list();void reload()=>setState(()=>future=api.list());Future<void> toggle(Recordatorio r)async{try{await api.update(r.id,{'completado':!r.completado});reload();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}Future<void> remove(Recordatorio r)async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Eliminar recordatorio'),content:Text('¿Eliminar "${r.titulo}"?'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Eliminar'))]));if(ok==true){await api.delete(r.id);reload();}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Mis Recordatorios'),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ServerSettingsScreen())),icon:const Icon(Icons.settings))]),body:RefreshIndicator(onRefresh:()async=>reload(),child:FutureBuilder<List<Recordatorio>>(future:future,builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text('No se pudo conectar: ${s.error}'),TextButton(onPressed:reload,child:const Text('Reintentar'))]));final items=s.data??[];if(items.isEmpty)return const Center(child:Text('Aún no tienes recordatorios'));return ListView.builder(itemCount:items.length,itemBuilder:(c,i){final r=items[i];final status=r.completado?'Completado':r.vencido?'Vencido':'Pendiente';return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:6),child:ListTile(leading:Checkbox(value:r.completado,onChanged:(_)=>toggle(r)),title:Text(r.titulo,style:TextStyle(decoration:r.completado?TextDecoration.lineThrough:null)),subtitle:Text('$status · ${r.fechaHora.day}/${r.fechaHora.month}/${r.fechaHora.year} ${r.fechaHora.hour.toString().padLeft(2,'0')}:${r.fechaHora.minute.toString().padLeft(2,'0')}\n${r.descripcion??''}'),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='edit'){final ok=await Navigator.push(context,MaterialPageRoute(builder:(_)=>RecordatorioForm(item:r)));if(ok==true)reload();}if(v=='delete')remove(r);},itemBuilder:(_)=>[const PopupMenuItem(value:'edit',child:Text('Editar')),const PopupMenuItem(value:'delete',child:Text('Eliminar'))])));});})),floatingActionButton:FloatingActionButton.extended(onPressed:()async{final ok=await Navigator.push(context,MaterialPageRoute(builder:(_)=>const RecordatorioForm()));if(ok==true)reload();},icon:const Icon(Icons.add),label:const Text('Nuevo')));}}